bool CvCityAI::AI_chooseProcess(CommerceTypes eCommerceType)
{
	ProcessTypes eBestProcess = AI_bestProcess(eCommerceType);
	// <!-- custom: Temporary military-production investigation: trace process helper choices because they can end production before ordinary unit selection. (GPT-5.6 Thinking) -->
	if (gMilitaryProductionLogLevel >= 3 && !isHuman() && !isBarbarian()) logBBAI("MILITARY_PRODUCTION_PROCESS_CHOICE turn=%d player=%d %S city=%S cityId=%d commerceType=%d process=%s processValue=%d chosen=%d",
		GC.getGame().getGameTurn(), getOwner(), GET_PLAYER(getOwner()).getCivilizationDescription(0), getName().GetCString(), getID(),
		eCommerceType, (eBestProcess == NO_PROCESS ? "-" : GC.getInfo(eBestProcess).getType()),
		(eBestProcess == NO_PROCESS ? 0 : AI_processValue(eBestProcess)), eBestProcess != NO_PROCESS);
	if (eBestProcess != NO_PROCESS)
	{
		pushOrder(ORDER_MAINTAIN, eBestProcess);
		return true;
	}
	return false;
}

// Returns true if a citizen was added to a plot...
// advc.enum: CityPlotTypes
// <!-- custom: hoisted from multiline signature between `peBestPlot` and `peBestSpecialist` by collapse_cpp_signatures.py. (GPT-5.5 (reviewed script output)) -->
bool CvCityAI::AI_addBestCitizen(bool bWorkers, bool bSpecialists, CityPlotTypes* peBestPlot, SpecialistTypes* peBestSpecialist)
{
	PROFILE_FUNC();

	int iGrowthValue = AI_growthValuePerFood(); // K-Mod

	int iBestValue = -1;
	SpecialistTypes eBestSpecialist = NO_SPECIALIST;
	static SpecialistTypes const eDefaultSpecialist = (SpecialistTypes)GC.getDEFAULT_SPECIALIST();

	if (bSpecialists)
	{
		// K-Mod. I've deleted a lot of original BtS code for handling forced specialists and replaced it with a simpler method.
		// We allow specialists only if they are either a forced type, or there are no forced types available.
		// (the original code attempted to assign specialists in the same proportions to their force counts.)
		bool bForcedSpecAvailable = false;
		if (isSpecialistForced()) // advc.opt
		{
			FOR_EACH_ENUM(Specialist)
			{
				if (getForceSpecialistCount(eLoopSpecialist) > 0 && isSpecialistValid(eLoopSpecialist, 1))
					bForcedSpecAvailable = true;
			}
		}
		FOR_EACH_ENUM(Specialist)
		{
			// <!-- custom: Keep the low-yield default Citizen out of ordinary job ranking; if no plot or productive specialist can absorb the population, the terminal fallback below may still use one so assignment cannot fail. See KI#44.5. (GPT-5.6-Sol) -->
			if (eLoopSpecialist == eDefaultSpecialist) continue;
			if (isSpecialistValid(eLoopSpecialist, 1) &&
				(!bForcedSpecAvailable || getForceSpecialistCount(eLoopSpecialist) > 0))
			{
				int iValue = AI_specialistValue(eLoopSpecialist, false, false, iGrowthValue);
				if (iValue > iBestValue)
				{
					iBestValue = iValue;
					eBestSpecialist = eLoopSpecialist;
				}
			}
		}
	}

	CityPlotTypes eBestPlot = NO_CITYPLOT;
	if (bWorkers)
	{
		for (CityPlotIter it(*this, false); it.hasNext(); ++it)
		{
			CvPlot const& kPlot = *it;
			CityPlotTypes const ePlot = it.currID();
			if (!isWorkingPlot(ePlot) && canWork(kPlot))
			{
				int iValue = AI_plotValue(kPlot, false, false, false, iGrowthValue);
				if (iValue > iBestValue)
				{
					iBestValue = iValue;
					eBestPlot = ePlot;
					eBestSpecialist = NO_SPECIALIST;
				}
			}
		}
	}

	if (eBestSpecialist != NO_SPECIALIST)
	{
		changeSpecialistCount(eBestSpecialist, 1);
		if (peBestPlot != NULL)
		{
			FAssert(peBestSpecialist != NULL);
			*peBestSpecialist = eBestSpecialist;
			*peBestPlot = NO_CITYPLOT;
		}
		return true;
	}
	else if (eBestPlot != NO_CITYPLOT)
	{
		setWorkingPlot(eBestPlot, true);
		if (peBestPlot != NULL)
		{
			FAssert(peBestSpecialist != NULL);
			*peBestSpecialist = NO_SPECIALIST;
			*peBestPlot = eBestPlot;

		}
		return true;
	}
	// <!-- custom: SAS's forbidden Citizen value converted the intended strong preference into an absolute impossibility and caused the recorded unassigned-population assertion cascade when war/blockade removed every normal job.
	// Use the default specialist only as the engine's final population-conservation fallback; it never competes with a legal plot or non-default specialist above.
	// This also preserves the human no-auto-Citizen convenience setting until a Citizen is genuinely unavoidable. See KI#44.5. (GPT-5.6-Sol) -->
	else if (bSpecialists && eDefaultSpecialist != NO_SPECIALIST && isSpecialistValid(eDefaultSpecialist, 1))
	{
		changeSpecialistCount(eDefaultSpecialist, 1);
		if (peBestPlot != NULL)
		{
			FAssert(peBestSpecialist != NULL);
			*peBestSpecialist = eDefaultSpecialist;
			*peBestPlot = NO_CITYPLOT;
		}
		return true;
	}

	return false;
}

// Returns true if a citizen was removed from a plot...
bool CvCityAI::AI_removeWorstCitizen(SpecialistTypes eIgnoreSpecialist)
{
	// if we are using more specialists than the free ones we get
	if (extraFreeSpecialists() < 0)
	{
		// <!-- custom: make these static const for performance optimization as advised by chatgpt 5 too. -->
		static const SpecialistTypes eDefaultSpecialist = (SpecialistTypes)GC.getDEFAULT_SPECIALIST();

		// does generic 'citizen' specialist exist?
		if (eDefaultSpecialist != NO_SPECIALIST)
		{
			// is ignore something other than generic citizen?
			if (eIgnoreSpecialist != eDefaultSpecialist)
			{
				// do we have at least one more generic citizen than we are forcing?
				if (getSpecialistCount(eDefaultSpecialist) >
					getForceSpecialistCount(eDefaultSpecialist))
				{
					// remove the extra generic citzen
					changeSpecialistCount(eDefaultSpecialist, -1);
					return true;
				}
			}
		}
	}

	//bAvoidGrowth = AI_avoidGrowth();
	//bIgnoreGrowth = AI_ignoreGrowth();
	int iGrowthValue = AI_growthValuePerFood();

	int iWorstValue = MAX_INT;
	SpecialistTypes eWorstSpecialist = NO_SPECIALIST;
	CityPlotTypes eWorstPlot = NO_CITYPLOT;

	// if we are using more specialists than the free ones we get
	if (extraFreeSpecialists() < 0)
	{
		FOR_EACH_ENUM(Specialist)
		{
			if (eIgnoreSpecialist == eLoopSpecialist ||
				getSpecialistCount(eLoopSpecialist) <= getForceSpecialistCount(eLoopSpecialist))
			{
				continue; // advc
			}
			int iValue = AI_specialistValue(eLoopSpecialist, true, false, iGrowthValue);
			if (iValue < iWorstValue)
			{
				iWorstValue = iValue;
				eWorstSpecialist = eLoopSpecialist;
				eWorstPlot = NO_CITYPLOT;
			}
		}
	}

	// check all the plots we are working
	for (WorkingPlotIter it(*this, false); it.hasNext(); ++it)
	{
		int iValue = AI_plotValue(*it, true, false, false, iGrowthValue);
		if (iValue < iWorstValue)
		{
			iWorstValue = iValue;
			eWorstSpecialist = NO_SPECIALIST;
			eWorstPlot = it.currID();
		}
	}

	if (eWorstSpecialist != NO_SPECIALIST)
	{
		changeSpecialistCount(eWorstSpecialist, -1);
		// K-Mod. If we had to remove a forced specialist, reduce the force count to match what we did.
		if (getSpecialistCount(eWorstSpecialist) < getForceSpecialistCount(eWorstSpecialist))
			setForceSpecialistCount(eWorstSpecialist, getSpecialistCount(eWorstSpecialist));
		//
		return true;
	}
	else if (eWorstPlot != NO_CITYPLOT)
	{
		setWorkingPlot(eWorstPlot, false);
		return true;
	}

	// if we still have not removed one, then try again, but do not ignore the one we were told to ignore
	if (extraFreeSpecialists() < 0)
	{
		FOR_EACH_ENUM(Specialist)
		{
			if (getSpecialistCount(eLoopSpecialist) <= 0)
				continue; // advc
			int iValue = AI_specialistValue(eLoopSpecialist, true, false, iGrowthValue);
			if (iValue < iWorstValue)
			{
				iWorstValue = iValue;
				eWorstSpecialist = eLoopSpecialist;
				eWorstPlot = NO_CITYPLOT;
			}
		}
	}

	if (eWorstSpecialist != NO_SPECIALIST)
	{
		changeSpecialistCount(eWorstSpecialist, -1);
		// <!-- custom: AdvCiv moved K-Mod's force-target repair away from this fallback, the only branch that can remove a fully forced specialist.
		// Lower the removed type's target so later assignment does not restore an impossible extra specialist. See KI#851. (ChatGPT-5.6-Sol + GPT-5.6-Sol) -->
		if (getSpecialistCount(eWorstSpecialist) < getForceSpecialistCount(eWorstSpecialist))
			setForceSpecialistCount(eWorstSpecialist, getSpecialistCount(eWorstSpecialist));
		return true;
	}

	return false;
}

// This function has been completely rewritten for K-Mod - original code deleted
void CvCityAI::AI_juggleCitizens(/* advc.131d: */ bool bEmphasize)
{
	PROFILE_FUNC();

	int iTotalFreeSpecialists = totalFreeSpecialists();
	bool bAnyForcedSpecs = isSpecialistForced();

	// work out how much food deficit would be acceptable
	int iStarvingAllowance = 0;
	// <!-- custom: cities starve too often, on top of failing to allocate best food tiles; make it stricter by not allowing any allowance, as advised by claude ai when asking it thanks to my prompts and or such or not contributions or not too -->
	// {
	// 	int iFoodLevel = getFood();
	// 	int iFoodToGrow = growthThreshold();
	// 	int iHappinessLevel = happyLevel() - unhappyLevel(0);

	// 	if (AI_isEmphasizeAvoidGrowth() || iHappinessLevel < (isHuman() ? 0 : 1))
	// 	{
	// 		iStarvingAllowance = std::max(0, (iFoodLevel - std::max(1, ((7 * iFoodToGrow) / 10))));
	// 		iStarvingAllowance /= (iHappinessLevel+getEspionageHappinessCounter()/2 >= 0 ? 2 : 1);
	// 	}
	// }

	//

	typedef std::pair<int, std::pair<bool,int> > PotentialJob_t; // (value, (isSpecialist, plot/specialist index))
	// I'd like to use std::tuple<int, bool, int>, but it isn't supported by this version of C++
	std::vector<PotentialJob_t> worked_jobs;
	std::vector<PotentialJob_t> unworked_jobs;
	std::vector<std::pair<bool, int> > new_jobs; // jobs assigned by this juggling process

	bool bDone = false;
	bool bAnyNewJobTaken = false; // advc.131d
	int iCycles = 0;
	do
	{
		int iGrowthValue = AI_growthValuePerFood(); // recalcuate on each cycle?
		int iFoodPerTurn = getYieldRate(YIELD_FOOD) - foodConsumption();

		worked_jobs.clear();
		unworked_jobs.clear();

		// populate jobs lists.
		// evaluate plots
		for (CityPlotIter it(*this, false); it.hasNext(); ++it)
		{
			CityPlotTypes const ePlot = it.currID();
			CvPlot const& kPlot = *it;
			if (isWorkingPlot(ePlot))
			{
				int iValue = AI_plotValue(kPlot, false, false, iFoodPerTurn >= 0, iGrowthValue);
				worked_jobs.push_back(PotentialJob_t(iValue, std::make_pair(false, ePlot)));
				// Note: the juggling process works better if worked and unworked plots are compared in the same way.
				// So I'm using 'bRemove = false' here even though we would be removing this worker.
			}
			else if (canWork(kPlot))
			{
				int iValue = AI_plotValue(kPlot, false, false, iFoodPerTurn >= 0, iGrowthValue);
				unworked_jobs.push_back(PotentialJob_t(iValue, std::make_pair(false, ePlot)));
			}
		}

		// check if it is still possible to assign new specialists of types that are forced
		bool bForcedSpecAvailable = false;
		if (bAnyForcedSpecs)
		{
			FOR_EACH_ENUM(Specialist)
			{
				if (getForceSpecialistCount(eLoopSpecialist) > 0 &&
					isSpecialistValid(eLoopSpecialist, 1))
				{
					bForcedSpecAvailable = true;
				}
			}
		}

		// evaluate specialists
		FOR_EACH_ENUM2(Specialist, e)
		{
			if (getSpecialistCount(e) > getForceSpecialistCount(e))
			{
				// don't allow unforced specialists unless none of the forced type are available
				int iValue = (bForcedSpecAvailable && getForceSpecialistCount(e) == 0 ? 0 :
						AI_specialistValue(e, false, false, iGrowthValue));
				worked_jobs.push_back(PotentialJob_t(iValue, std::make_pair(true, e)));
			}
			if (isSpecialistValid(e, 1))
			{
				int iValue = (bForcedSpecAvailable && getForceSpecialistCount(e) == 0 ? 0 :
						AI_specialistValue(e, false, false, iGrowthValue));
				unworked_jobs.push_back(PotentialJob_t(iValue, std::make_pair(true, e)));
				if (getForceSpecialistCount(e) > 0)
					bForcedSpecAvailable = true;
			}
		}

		//
		std::sort(worked_jobs.begin(), worked_jobs.end());
		std::sort(unworked_jobs.begin(), unworked_jobs.end(), std::greater<PotentialJob_t>());
		// if values are equal - prefer to work the specialist job. (perhaps a different city can use the plot)
		// Note: PotentialJob_t is (value, (bSpecialist, index)), and bSpecialist == true is a higher value than bSpecialist == false.

		std::vector<PotentialJob_t>::iterator worked_it = worked_jobs.begin();
		std::vector<PotentialJob_t>::iterator unworked_it = unworked_jobs.begin();
		bool bTakeNewJob = false;

		while (!bTakeNewJob && worked_it != worked_jobs.end() && unworked_it != unworked_jobs.end()
			&& unworked_it->first > worked_it->first)
		{
			bTakeNewJob = true; // default position is the take the new job.

			// Don't take the job if it would make us starve
			int iCurrentFood = worked_it->second.first
				? GET_PLAYER(getOwner()).specialistYield((SpecialistTypes)worked_it->second.second, YIELD_FOOD)
				: getCityIndexPlot((CityPlotTypes)worked_it->second.second)->getYield(YIELD_FOOD);

			int iNextFood = unworked_it->second.first
				? GET_PLAYER(getOwner()).specialistYield((SpecialistTypes)unworked_it->second.second, YIELD_FOOD)
				: getCityIndexPlot((CityPlotTypes)unworked_it->second.second)->getYield(YIELD_FOOD);

			// <!-- custom: seemingly a bug found by claude ai; i am not sure this is really a bug, indeed ingame cities are starving without allocating improved sheep or such high tiles (see as of now known issue 34 in docs with screenshots there in the google drive) -->
			// OLD: Only avoid starvation if we're not already starving
			// if (iFoodPerTurn >= 0 && iFoodPerTurn + iNextFood - iCurrentFood + iStarvingAllowance < 0)
			// <!-- custom: Our earlier AdvCiv-SAS change above improved Base AdvCiv by blocking job swaps that worsen an existing food deficit, but became overstrict by also blocking any improvement that did not eliminate the entire deficit immediately.
			// Save file 428 BBAI logging showed Bursa keep 4-5 Artists while starving by 5-7 food because working its available 4-food plot would still leave a smaller deficit, despite the full city-aware comparison strongly preferring that plot.
			// Continue blocking food reductions while starving, but allow equal-food swaps and partial recovery. (GPT-5.5) -->
			if (iFoodPerTurn + iNextFood - iCurrentFood + iStarvingAllowance < 0 && iNextFood < iCurrentFood)
			{
				bTakeNewJob = false;
			}
			// block removal of free specialists
			else if (worked_it->second.first && !unworked_it->second.first &&
				getSpecialistPopulation() <= iTotalFreeSpecialists)
			{
				bTakeNewJob = false;
			}
			// if forced specialists are still available, don't allow non-forced specialists.
			else if ((bForcedSpecAvailable || (worked_it->second.first && getForceSpecialistCount((SpecialistTypes)worked_it->second.second) > 0)) &&
				unworked_it->second.first && getForceSpecialistCount((SpecialistTypes)unworked_it->second.second) == 0)
			{
				bTakeNewJob = false;
			}
			// don't remove jobs that were assigned by the juggling process
			else if (std::find(new_jobs.begin(), new_jobs.end(), worked_it->second) != new_jobs.end())
			{
				bTakeNewJob = false;
			}
			// finally, don't take the new job if a direct comparison shows that it is not more valuable than the old job.
			// (exception, switching away from zero-value jobs, such as unwanted specialists)
			else if (worked_it->first > 0 && AI_jobChangeValue(unworked_it->second, worked_it->second, false, false, iGrowthValue) <= 0)
			{
				bTakeNewJob = false;
			}

			// If we can't do this job switch, check another option. Loop through worked jobs first, then unworked jobs.
			if (!bTakeNewJob)
			{
				++worked_it;
				if (worked_it == worked_jobs.end() || worked_it->first >= unworked_it->first)
				{
					worked_it = worked_jobs.begin();
					++unworked_it;
				}
			}
			// else we're done.
		}

		// <!-- custom: If K-Mod's fast approximate prefilter gives up, try one guarded direct plot-to-plot fallback.
		// The raw 3F + 2H + 1C diagnostic proved too naive for final behavior, but it is useful as a cheap suspicion filter.
		// Only plot pairs that are strict yield upgrades, modest or nonnegative-raw food gains, large food/commerce gains, or large weighted raw gains without food loss are tested here, and the normal contextual AI_jobChangeValue check still decides whether the swap is actually good.
		// Apply at most one swap, then recalculate. (ChatGPT-5.5 + GPT-5.5) -->
		// <!-- custom: Map 428 still logged 3,702 plot-to-plot contextual-miss records; recurring high-value cases worked 2F/1H/1C instead of 3F/0H/1C or 3F/1H/1C instead of 4F/0H/1C because the approximate prefilter undervalued one additional food.
		// Test the narrow at-least +1F for at most -1H/-2C pattern here, but require the full city-aware comparison below to approve it. (GPT-5.5) -->
		// <!-- custom: The subsequent full 500-turn save file 428 run still logged 524 food-positive misses that were nonnegative under the diagnostic 3F + 2H + 1C score; 135 had a contextual gain above 1,000, and the most common uncovered pattern was 140 +1F/0H/-3C records.
		// Use that raw score only to expose candidates, then continue requiring the full city-aware comparison below to approve the swap. (GPT-5.5) -->
		// <!-- custom: Human cities reach AI_juggleCitizens only while citizen automation is enabled; optionally share this safe fallback without changing manual citizen assignments. (GPT-5.5) -->
		static bool const bHumanCitizenPlotFallback = GC.getDefineBOOL("SAS_CONVENIENCE_HUMAN_CITIZEN_PLOT_FALLBACK_ENABLE");
		if (!bTakeNewJob && (!isHuman() || bHumanCitizenPlotFallback))
		{
			bool const bLogCitizenFallback = (gCitizenLogLevel >= 2);
			std::vector<PotentialJob_t>::iterator bestFallbackWorked = worked_jobs.end();
			std::vector<PotentialJob_t>::iterator bestFallbackUnworked = unworked_jobs.end();
			int iBestFallbackValue = 0;
			int iBestFallbackRaw321Delta = 0;
			char const* szBestFallbackReason = NULL;
			for (std::vector<PotentialJob_t>::iterator workedFallback = worked_jobs.begin(); workedFallback != worked_jobs.end(); ++workedFallback)
			{
				if (workedFallback->second.first)
					continue;
				CvPlot const& kWorkedPlot = *getCityIndexPlot((CityPlotTypes)workedFallback->second.second);
				for (std::vector<PotentialJob_t>::iterator unworkedFallback = unworked_jobs.begin(); unworkedFallback != unworked_jobs.end(); ++unworkedFallback)
				{
					if (unworkedFallback->second.first || unworkedFallback->first > workedFallback->first)
						continue;
					CvPlot const& kUnworkedPlot = *getCityIndexPlot((CityPlotTypes)unworkedFallback->second.second);
					int const iFoodDelta = kUnworkedPlot.getYield(YIELD_FOOD) - kWorkedPlot.getYield(YIELD_FOOD);
					int const iProductionDelta = kUnworkedPlot.getYield(YIELD_PRODUCTION) - kWorkedPlot.getYield(YIELD_PRODUCTION);
					int const iCommerceDelta = kUnworkedPlot.getYield(YIELD_COMMERCE) - kWorkedPlot.getYield(YIELD_COMMERCE);
					bool const bStrictYieldUpgrade = (iFoodDelta >= 0 && iProductionDelta >= 0 && iCommerceDelta >= 0 && (iFoodDelta > 0 || iProductionDelta > 0 || iCommerceDelta > 0));
					int const iRaw321Delta = 3 * iFoodDelta + 2 * iProductionDelta + iCommerceDelta;
					bool const bModestFoodTrade = (iFoodDelta >= 1 && iProductionDelta >= -1 && iCommerceDelta >= -2);
					bool const bNonnegativeRawFoodTrade = (iFoodDelta >= 1 && iRaw321Delta >= 0);
					bool const bLargeFoodCommerceGain = (iFoodDelta >= 2 && iCommerceDelta >= 3 && iProductionDelta >= -3);
					bool const bLargeRawGainWithoutFoodLoss = (iFoodDelta >= 0 && iProductionDelta >= -2 && iRaw321Delta >= 4);
					if (!bStrictYieldUpgrade && !bModestFoodTrade && !bNonnegativeRawFoodTrade && !bLargeFoodCommerceGain && !bLargeRawGainWithoutFoodLoss)
						continue;

					if (iFoodPerTurn + iFoodDelta + iStarvingAllowance < 0 && iFoodDelta < 0)
						continue;
					if (std::find(new_jobs.begin(), new_jobs.end(), workedFallback->second) != new_jobs.end())
						continue;

					int const iContextValue = AI_jobChangeValue(unworkedFallback->second, workedFallback->second, false, false, iGrowthValue);
					if (iContextValue > iBestFallbackValue)
					{
						iBestFallbackValue = iContextValue;
						if (bLogCitizenFallback)
						{
							iBestFallbackRaw321Delta = iRaw321Delta;
							szBestFallbackReason = (bStrictYieldUpgrade ? "STRICT_YIELD" : (bModestFoodTrade ? "MODEST_FOOD_TRADE" : (bNonnegativeRawFoodTrade ? "NONNEGATIVE_RAW_FOOD_TRADE" : (bLargeFoodCommerceGain ? "LARGE_FOOD_COMMERCE" : "LARGE_RAW_NO_FOOD_LOSS"))));
						}
						bestFallbackWorked = workedFallback;
						bestFallbackUnworked = unworkedFallback;
					}
				}
			}
			if (bestFallbackWorked != worked_jobs.end())
			{
				worked_it = bestFallbackWorked;
				unworked_it = bestFallbackUnworked;
				bTakeNewJob = true;
				if (bLogCitizenFallback)
				{
					CvPlot const& kWorkedPlot = *getCityIndexPlot((CityPlotTypes)worked_it->second.second);
					CvPlot const& kUnworkedPlot = *getCityIndexPlot((CityPlotTypes)unworked_it->second.second);
					logBBAI("CITIZEN_CONTEXT_FALLBACK_TAKE turn=%d player=%d %S city=%S cityId=%d fallbackReason=%s raw321Delta=%d contextValue=%d approximateDelta=%d oldPlot=(%d,%d) oldFood=%d oldProduction=%d oldCommerce=%d newPlot=(%d,%d) newFood=%d newProduction=%d newCommerce=%d",
						GC.getGame().getGameTurn(), getOwner(), GET_PLAYER(getOwner()).getCivilizationShortDescription(),
						getName().GetCString(), getID(), szBestFallbackReason, iBestFallbackRaw321Delta, iBestFallbackValue,
						unworked_it->first - worked_it->first, kWorkedPlot.getX(), kWorkedPlot.getY(), kWorkedPlot.getYield(YIELD_FOOD),
						kWorkedPlot.getYield(YIELD_PRODUCTION), kWorkedPlot.getYield(YIELD_COMMERCE), kUnworkedPlot.getX(),
						kUnworkedPlot.getY(), kUnworkedPlot.getYield(YIELD_FOOD), kUnworkedPlot.getYield(YIELD_PRODUCTION),
						kUnworkedPlot.getYield(YIELD_COMMERCE));
				}
			}
		}

		// <!-- custom: After the guarded plot-to-plot fallback, try one AI-only specialist fallback for specialist-to-plot and specialist-to-specialist swaps that K-Mod's approximate prefilter still hides.
		// This deliberately avoids plot-to-specialist hires, because those are more likely to revive the excessive-specialist issues that the growth-first rules are meant to suppress.
		// Free specialists can switch type but cannot be reassigned to work a city plot.
		// As with the plot fallback, the direct contextual AI_jobChangeValue check still decides and at most one swap is applied before recalculation. (ChatGPT-5.5 + GPT-5.5 review) -->
		if (!bTakeNewJob && !isHuman())
		{
			bool const bLogSpecialistFallback = (gCitizenLogLevel >= 2);
			CvPlayerAI const& kOwner = GET_PLAYER(getOwner());
			std::vector<PotentialJob_t>::iterator bestSpecialistFallbackWorked = worked_jobs.end();
			std::vector<PotentialJob_t>::iterator bestSpecialistFallbackUnworked = unworked_jobs.end();
			int iBestSpecialistFallbackValue = 0;
			char const* szBestSpecialistFallbackType = NULL;
			for (std::vector<PotentialJob_t>::iterator workedFallback = worked_jobs.begin(); workedFallback != worked_jobs.end(); ++workedFallback)
			{
				if (!workedFallback->second.first)
					continue;
				int const iCurrentFood = kOwner.specialistYield((SpecialistTypes)workedFallback->second.second, YIELD_FOOD);
				for (std::vector<PotentialJob_t>::iterator unworkedFallback = unworked_jobs.begin(); unworkedFallback != unworked_jobs.end(); ++unworkedFallback)
				{
					if (unworkedFallback->second == workedFallback->second || unworkedFallback->first > workedFallback->first)
						continue;
					bool const bSpecialistToSpecialist = unworkedFallback->second.first;
					bool const bSpecialistToPlot = !unworkedFallback->second.first;

					int const iNextFood = (bSpecialistToSpecialist ? kOwner.specialistYield((SpecialistTypes)unworkedFallback->second.second, YIELD_FOOD) : getCityIndexPlot((CityPlotTypes)unworkedFallback->second.second)->getYield(YIELD_FOOD));
					if (iFoodPerTurn + iNextFood - iCurrentFood + iStarvingAllowance < 0 && iNextFood < iCurrentFood)
						continue;
					if (bSpecialistToPlot && getSpecialistPopulation() <= iTotalFreeSpecialists)
						continue;
					if (bSpecialistToSpecialist && (bForcedSpecAvailable || getForceSpecialistCount((SpecialistTypes)workedFallback->second.second) > 0) && getForceSpecialistCount((SpecialistTypes)unworkedFallback->second.second) == 0)
						continue;
					if (std::find(new_jobs.begin(), new_jobs.end(), workedFallback->second) != new_jobs.end())
						continue;

					int const iContextValue = AI_jobChangeValue(unworkedFallback->second, workedFallback->second, false, false, iGrowthValue);
					if (iContextValue > iBestSpecialistFallbackValue)
					{
						iBestSpecialistFallbackValue = iContextValue;
						bestSpecialistFallbackWorked = workedFallback;
						bestSpecialistFallbackUnworked = unworkedFallback;
						if (bLogSpecialistFallback)
							szBestSpecialistFallbackType = (bSpecialistToSpecialist ? "SPECIALIST_TO_SPECIALIST" : "SPECIALIST_TO_PLOT");
					}
				}
			}
			if (bestSpecialistFallbackWorked != worked_jobs.end())
			{
				worked_it = bestSpecialistFallbackWorked;
				unworked_it = bestSpecialistFallbackUnworked;
				bTakeNewJob = true;
				if (bLogSpecialistFallback)
				{
					bool const bUnworkedSpecialist = unworked_it->second.first;
					SpecialistTypes const eWorkedSpecialist = (SpecialistTypes)worked_it->second.second;
					SpecialistTypes const eUnworkedSpecialist = (bUnworkedSpecialist ? (SpecialistTypes)unworked_it->second.second : NO_SPECIALIST);
					CvPlot const* pUnworkedPlot = (bUnworkedSpecialist ? NULL : getCityIndexPlot((CityPlotTypes)unworked_it->second.second));
					logBBAI("CITIZEN_SPECIALIST_FALLBACK_TAKE turn=%d player=%d %S city=%S cityId=%d fallbackType=%s contextValue=%d approximateDelta=%d oldJob=%s oldIndex=%d oldFood=%d oldProduction=%d oldCommerce=%d newJob=%s newIndex=%d newX=%d newY=%d newFood=%d newProduction=%d newCommerce=%d",
						GC.getGame().getGameTurn(), getOwner(), kOwner.getCivilizationShortDescription(), getName().GetCString(), getID(),
						szBestSpecialistFallbackType, iBestSpecialistFallbackValue, unworked_it->first - worked_it->first,
						GC.getInfo(eWorkedSpecialist).getType(), worked_it->second.second,
						kOwner.specialistYield(eWorkedSpecialist, YIELD_FOOD), kOwner.specialistYield(eWorkedSpecialist, YIELD_PRODUCTION),
						kOwner.specialistYield(eWorkedSpecialist, YIELD_COMMERCE),
						(bUnworkedSpecialist ? GC.getInfo(eUnworkedSpecialist).getType() : "PLOT"), unworked_it->second.second,
						(pUnworkedPlot == NULL ? -1 : pUnworkedPlot->getX()), (pUnworkedPlot == NULL ? -1 : pUnworkedPlot->getY()),
						(bUnworkedSpecialist ? kOwner.specialistYield(eUnworkedSpecialist, YIELD_FOOD) : pUnworkedPlot->getYield(YIELD_FOOD)),
						(bUnworkedSpecialist ? kOwner.specialistYield(eUnworkedSpecialist, YIELD_PRODUCTION) : pUnworkedPlot->getYield(YIELD_PRODUCTION)),
						(bUnworkedSpecialist ? kOwner.specialistYield(eUnworkedSpecialist, YIELD_COMMERCE) : pUnworkedPlot->getYield(YIELD_COMMERCE)));
				}
			}
		}

		if (!bTakeNewJob)
		{
			// <!-- custom: K-Mod orders candidate jobs by approximate standalone values and stops before contextual AI_jobChangeValue comparisons once the best unworked approximation is no better than the worst worked one.
			// At citizen log level 3, audit the final allocation for positive contextual swaps hidden by that prefilter.
			// Also report the strongest non-upgrading plot disagreement under the deliberately simple diagnostic score 3F + 2H + 1C; this second signal is not itself proof of a bad assignment because city priorities still matter. (GPT-5.5) -->
			if (gCitizenLogLevel >= 3 && !isHuman())
			{
				PotentialJob_t const* pBestMissedWorkedJob = NULL;
				PotentialJob_t const* pBestMissedUnworkedJob = NULL;
				int iBestMissedContextValue = 0;
				int iMissedContextCount = 0;
				PotentialJob_t const* pBestRawWorkedJob = NULL;
				PotentialJob_t const* pBestRawUnworkedJob = NULL;
				int iBestRawDelta = 0;
				int iBestRawContextValue = 0;
				int iRawSuspectCount = 0;
				for (std::vector<PotentialJob_t>::const_iterator workedAudit = worked_jobs.begin(); workedAudit != worked_jobs.end(); ++workedAudit)
				{
					for (std::vector<PotentialJob_t>::const_iterator unworkedAudit = unworked_jobs.begin(); unworkedAudit != unworked_jobs.end(); ++unworkedAudit)
					{
						if (workedAudit->second == unworkedAudit->second)
							continue;
						int iContextValue = MIN_INT;
						bool const bHiddenByApproximatePrefilter = (unworkedAudit->first <= workedAudit->first);
						if (bHiddenByApproximatePrefilter)
						{
							int const iCurrentFood = (workedAudit->second.first ? GET_PLAYER(getOwner()).specialistYield((SpecialistTypes)workedAudit->second.second, YIELD_FOOD) : getCityIndexPlot((CityPlotTypes)workedAudit->second.second)->getYield(YIELD_FOOD));
							int const iNextFood = (unworkedAudit->second.first ? GET_PLAYER(getOwner()).specialistYield((SpecialistTypes)unworkedAudit->second.second, YIELD_FOOD) : getCityIndexPlot((CityPlotTypes)unworkedAudit->second.second)->getYield(YIELD_FOOD));
							bool const bWouldWorsenStarvation = (iFoodPerTurn + iNextFood - iCurrentFood + iStarvingAllowance < 0 && iNextFood < iCurrentFood);
							bool const bWouldRemoveFreeSpecialist = (workedAudit->second.first && !unworkedAudit->second.first && getSpecialistPopulation() <= iTotalFreeSpecialists);
							bool const bWouldBreakForcedSpecialist = ((bForcedSpecAvailable || (workedAudit->second.first && getForceSpecialistCount((SpecialistTypes)workedAudit->second.second) > 0)) && unworkedAudit->second.first && getForceSpecialistCount((SpecialistTypes)unworkedAudit->second.second) == 0);
							bool const bWouldUndoJuggleJob = (std::find(new_jobs.begin(), new_jobs.end(), workedAudit->second) != new_jobs.end());
							if (!bWouldWorsenStarvation && !bWouldRemoveFreeSpecialist && !bWouldBreakForcedSpecialist && !bWouldUndoJuggleJob)
							{
								iContextValue = AI_jobChangeValue(unworkedAudit->second, workedAudit->second, false, false, iGrowthValue);
								if (iContextValue > 0)
								{
									iMissedContextCount++;
									if (iContextValue > iBestMissedContextValue)
									{
										iBestMissedContextValue = iContextValue;
										pBestMissedWorkedJob = &*workedAudit;
										pBestMissedUnworkedJob = &*unworkedAudit;
									}
								}
							}
						}
						if (!workedAudit->second.first && !unworkedAudit->second.first)
						{
							CvPlot const& kWorkedPlot = *getCityIndexPlot((CityPlotTypes)workedAudit->second.second);
							CvPlot const& kUnworkedPlot = *getCityIndexPlot((CityPlotTypes)unworkedAudit->second.second);
							ImprovementTypes const eWorkedImprovement = kWorkedPlot.getImprovementType();
							bool const bWorkedImprovementUpgrades = (eWorkedImprovement != NO_IMPROVEMENT && GC.getInfo(eWorkedImprovement).getImprovementUpgrade() != NO_IMPROVEMENT);
							int const iWorkedRawScore = 3 * kWorkedPlot.getYield(YIELD_FOOD) + 2 * kWorkedPlot.getYield(YIELD_PRODUCTION) + kWorkedPlot.getYield(YIELD_COMMERCE);
							int const iUnworkedRawScore = 3 * kUnworkedPlot.getYield(YIELD_FOOD) + 2 * kUnworkedPlot.getYield(YIELD_PRODUCTION) + kUnworkedPlot.getYield(YIELD_COMMERCE);
							int const iRawDelta = iUnworkedRawScore - iWorkedRawScore;
							if (!bWorkedImprovementUpgrades && iRawDelta > 0)
							{
								if (iContextValue == MIN_INT)
									iContextValue = AI_jobChangeValue(unworkedAudit->second, workedAudit->second, false, false, iGrowthValue);
								iRawSuspectCount++;
								if (iRawDelta > iBestRawDelta)
								{
									iBestRawDelta = iRawDelta;
									iBestRawContextValue = iContextValue;
									pBestRawWorkedJob = &*workedAudit;
									pBestRawUnworkedJob = &*unworkedAudit;
								}
							}
						}
					}
				}
				if (pBestMissedWorkedJob != NULL)
				{
					bool const bWorkedSpecialist = pBestMissedWorkedJob->second.first;
					bool const bUnworkedSpecialist = pBestMissedUnworkedJob->second.first;
					CvPlot const* pWorkedPlot = (bWorkedSpecialist ? NULL : getCityIndexPlot((CityPlotTypes)pBestMissedWorkedJob->second.second));
					CvPlot const* pUnworkedPlot = (bUnworkedSpecialist ? NULL : getCityIndexPlot((CityPlotTypes)pBestMissedUnworkedJob->second.second));
					SpecialistTypes const eWorkedSpecialist = (bWorkedSpecialist ? (SpecialistTypes)pBestMissedWorkedJob->second.second : NO_SPECIALIST);
					SpecialistTypes const eUnworkedSpecialist = (bUnworkedSpecialist ? (SpecialistTypes)pBestMissedUnworkedJob->second.second : NO_SPECIALIST);
					logBBAI("CITIZEN_CONTEXT_SWAP_MISSED turn=%d player=%d %S city=%S cityId=%d missedPairs=%d contextValue=%d approximateDelta=%d oldJob=%s oldIndex=%d oldX=%d oldY=%d oldFood=%d oldProduction=%d oldCommerce=%d newJob=%s newIndex=%d newX=%d newY=%d newFood=%d newProduction=%d newCommerce=%d",
						GC.getGame().getGameTurn(), getOwner(), GET_PLAYER(getOwner()).getCivilizationShortDescription(),
						getName().GetCString(), getID(), iMissedContextCount, iBestMissedContextValue,
						pBestMissedUnworkedJob->first - pBestMissedWorkedJob->first,
						(bWorkedSpecialist ? GC.getInfo(eWorkedSpecialist).getType() : "PLOT"), pBestMissedWorkedJob->second.second,
						(pWorkedPlot == NULL ? -1 : pWorkedPlot->getX()), (pWorkedPlot == NULL ? -1 : pWorkedPlot->getY()),
						(bWorkedSpecialist ? GET_PLAYER(getOwner()).specialistYield(eWorkedSpecialist, YIELD_FOOD) : pWorkedPlot->getYield(YIELD_FOOD)),
						(bWorkedSpecialist ? GET_PLAYER(getOwner()).specialistYield(eWorkedSpecialist, YIELD_PRODUCTION) : pWorkedPlot->getYield(YIELD_PRODUCTION)),
						(bWorkedSpecialist ? GET_PLAYER(getOwner()).specialistYield(eWorkedSpecialist, YIELD_COMMERCE) : pWorkedPlot->getYield(YIELD_COMMERCE)),
						(bUnworkedSpecialist ? GC.getInfo(eUnworkedSpecialist).getType() : "PLOT"), pBestMissedUnworkedJob->second.second,
						(pUnworkedPlot == NULL ? -1 : pUnworkedPlot->getX()), (pUnworkedPlot == NULL ? -1 : pUnworkedPlot->getY()),
						(bUnworkedSpecialist ? GET_PLAYER(getOwner()).specialistYield(eUnworkedSpecialist, YIELD_FOOD) : pUnworkedPlot->getYield(YIELD_FOOD)),
						(bUnworkedSpecialist ? GET_PLAYER(getOwner()).specialistYield(eUnworkedSpecialist, YIELD_PRODUCTION) : pUnworkedPlot->getYield(YIELD_PRODUCTION)),
						(bUnworkedSpecialist ? GET_PLAYER(getOwner()).specialistYield(eUnworkedSpecialist, YIELD_COMMERCE) : pUnworkedPlot->getYield(YIELD_COMMERCE)));
				}
				if (pBestRawWorkedJob != NULL)
				{
					CvPlot const& kWorkedPlot = *getCityIndexPlot((CityPlotTypes)pBestRawWorkedJob->second.second);
					CvPlot const& kUnworkedPlot = *getCityIndexPlot((CityPlotTypes)pBestRawUnworkedJob->second.second);
					ImprovementTypes const eWorkedImprovement = kWorkedPlot.getImprovementType();
					ImprovementTypes const eUnworkedImprovement = kUnworkedPlot.getImprovementType();
					logBBAI("CITIZEN_RAW_PLOT_SUSPECT turn=%d player=%d %S city=%S cityId=%d suspectPairs=%d raw321Delta=%d contextValue=%d approximateDelta=%d oldPlot=(%d,%d) oldFood=%d oldProduction=%d oldCommerce=%d oldImprovement=%s newPlot=(%d,%d) newFood=%d newProduction=%d newCommerce=%d newImprovement=%s",
						GC.getGame().getGameTurn(), getOwner(), GET_PLAYER(getOwner()).getCivilizationShortDescription(),
						getName().GetCString(), getID(), iRawSuspectCount, iBestRawDelta, iBestRawContextValue,
						pBestRawUnworkedJob->first - pBestRawWorkedJob->first, kWorkedPlot.getX(), kWorkedPlot.getY(),
						kWorkedPlot.getYield(YIELD_FOOD), kWorkedPlot.getYield(YIELD_PRODUCTION), kWorkedPlot.getYield(YIELD_COMMERCE),
						(eWorkedImprovement == NO_IMPROVEMENT ? "NONE" : GC.getInfo(eWorkedImprovement).getType()), kUnworkedPlot.getX(),
						kUnworkedPlot.getY(), kUnworkedPlot.getYield(YIELD_FOOD), kUnworkedPlot.getYield(YIELD_PRODUCTION),
						kUnworkedPlot.getYield(YIELD_COMMERCE),
						(eUnworkedImprovement == NO_IMPROVEMENT ? "NONE" : GC.getInfo(eUnworkedImprovement).getType()));
				}
			}
			bDone = true; // no more job swaps. So we're finished.
		}
		else
		{
			bAnyNewJobTaken = true; // advc.131d
			// remove the current job
			if (worked_it->second.first)
			{
				FAssert(getSpecialistCount((SpecialistTypes)worked_it->second.second) > 0);
				changeSpecialistCount((SpecialistTypes)worked_it->second.second, -1);
			}
			else
			{
				FAssert(isWorkingPlot((CityPlotTypes)worked_it->second.second));
				setWorkingPlot((CityPlotTypes)worked_it->second.second, false);
			}

			// assign the new job
			if (unworked_it->second.first)
			{
				FAssert(isSpecialistValid((SpecialistTypes)unworked_it->second.second, 1));
				changeSpecialistCount((SpecialistTypes)unworked_it->second.second, 1);
			}
			else
			{
				FAssert(!isWorkingPlot((CityPlotTypes)unworked_it->second.second));
				setWorkingPlot((CityPlotTypes)unworked_it->second.second, true);
			}
			// add the new job to the new jobs list
			new_jobs.push_back(unworked_it->second);
		}

		if (iCycles > getPopulation() + iTotalFreeSpecialists)
		{
			// This isn't a serious problem. I just want to know how offen it happens.
			//FErrorMsg("juggle citizens failed to find a stable solution.");
			PROFILE("juggle citizen failure");
			bDone = true;
		}
		iCycles++;
	} while (!bDone);
	// <advc.131d>
	if (bEmphasize && isHuman() && !bAnyNewJobTaken && !AI_isStrongEmphasis())
	{
		/*	The player probably wanted there to be a change.
			Let's try harder. */
		AI_setStrongEmphasis(true);
	} // </advc.131d>
	// Record keeping, to test efficiency.
#ifdef LOG_JUGGLE_CITIZENS
	{
		TCHAR message[20];
		_snprintf(message, 20, "%d+%d : %d\n", getPopulation(), iTotalFreeSpecialists, iCycles);
		gDLL->logMsg("juggle_log.txt", message ,false, false);
	}
#endif
}

/*	K-Mod: Estimate the cost of recovery after losing iQuantity number of citizens
	in this city. (units of 4x commerce.) Replacing AI_citizenLossCost in BtS. */
int CvCityAI::AI_citizenSacrificeCost(int iCitLoss, int iHappyLevel, int iNewAnger, int iAngerTimer)
{
	PROFILE_FUNC();

	CvPlayerAI const& kOwner = GET_PLAYER(getOwner());

	iCitLoss = std::min(getPopulation()-1, iCitLoss);
	if (iCitLoss < 1)
		return 0;

	if (isNoUnhappiness())
	{
		iNewAnger = 0;
		iAngerTimer = 0;
	}

	int iYields[NUM_YIELD_TYPES] = {};
	int iYieldWeights[NUM_YIELD_TYPES] =
	{
		9, // food
		7, // production
		4, // commerce
	}; // <advc.121b>
	if(isCapital())
		iYieldWeights[YIELD_COMMERCE]++; // </advc.121b>
	std::vector<int> job_scores;
	int iTotalScore = 0;

	for (int i = 0; i < -iHappyLevel; i++)
		job_scores.push_back(0);

	if ((int)job_scores.size() < iCitLoss)
	{
		for (WorkingPlotIter it(*this, false); it.hasNext(); ++it)
		{
			CvPlot const& kPlot = *it;
			FAssert(kPlot.getWorkingCity() == this);
			// ideally, the plots would be scored using AI_plotValue, but I'm worried that would be too slow.
			// so here's a really rough estimate of the plot value
			int iPlotScore = 0;
			for (int j = 0; j < NUM_YIELD_TYPES; j++)
			{
				int y = kPlot.getYield((YieldTypes)j);
				iYields[j] += y;
				iPlotScore += y * iYieldWeights[j];
			}
			if (kPlot.isImproved() &&
				GC.getInfo(kPlot.getImprovementType()).getImprovementUpgrade() != NO_IMPROVEMENT)
			{
				iYields[YIELD_COMMERCE] += 2;
				iPlotScore += 2 * iYieldWeights[YIELD_COMMERCE];
			}
			/*	<advc.121b> Anticipate improvement. CitySiteEvaluator has proper code
				for this, but don't want to go through all improvements here. */
			if (!kPlot.isImproved() && AI_getWorkersHave() > 0)
				iPlotScore *= 2; // </advc.121b>
			iTotalScore += iPlotScore;
			job_scores.push_back(iPlotScore);
		}
	}
	if ((int)job_scores.size() < iCitLoss)
	{
		FOR_EACH_ENUM(Specialist)
		{
			int const iSpecialistCount = getSpecialistCount(eLoopSpecialist);
			if (iSpecialistCount <= 0)
				continue; // advc
			// <!-- custom: K-Mod multiplied the job count and score by assigned specialists but accumulated this type's yields only once.
			// Apply the same multiplicity to aggregate yields so repeated same-type specialists cannot become a negative sacrifice subsidy. See KI#847. (ChatGPT-5.6-Sol + GPT-5.6-Sol) -->
			// very rough..
			int iSpecScore = 0;
			for (int j = 0; j < NUM_YIELD_TYPES; j++)
			{
				int y = kOwner.specialistYield(eLoopSpecialist, (YieldTypes)j)*3/2;
				iYields[j] += y * iSpecialistCount;
				iSpecScore += y * iYieldWeights[j];
			}
			FOR_EACH_ENUM(Commerce)
			{
				int c = kOwner.specialistCommerce(eLoopSpecialist, eLoopCommerce)*3/2;
				iYields[YIELD_COMMERCE] += c * iSpecialistCount;
				iSpecScore += c * iYieldWeights[YIELD_COMMERCE];
			}
			iTotalScore += iSpecScore * iSpecialistCount;
			job_scores.resize(job_scores.size() + iSpecialistCount, iSpecScore);
		}
	}

	if ((int)job_scores.size() < iCitLoss)
	{
		FErrorMsg("Not enough job data to calculate citizen loss cost.");
		int iBogusData = (1+GC.getFOOD_CONSUMPTION_PER_POPULATION()) * iYieldWeights[YIELD_FOOD];
		job_scores.resize(iCitLoss, iBogusData);
		iTotalScore += iBogusData;
	}

	FAssert((int)job_scores.size() >= iCitLoss);
	std::partial_sort(job_scores.begin(), job_scores.begin()+iCitLoss, job_scores.end());
	int iAverageScore = intdiv::round(iTotalScore, job_scores.size());

	int iWastedFood = -healthRate();
	int iTotalFood = getYieldRate(YIELD_FOOD) - iWastedFood;

	// calculate the total cost-per-turn from missing iCitLoss citizens.
	int iBaseCostPerTurn = 0;
	for (int j = 0; j < NUM_YIELD_TYPES; j++)
	{
		if (iYields[j] > 0)
			iBaseCostPerTurn += 4 * iYields[j] * AI_yieldMultiplier((YieldTypes)j) * kOwner.AI_yieldWeight((YieldTypes)j) / 100;
	}
	// reduce value of food used for production - otherwise our citizens might be overvalued due to working extra food.
	if (isFoodProduction())
	{
		int iExtraFood = iTotalFood - getPopulation() * GC.getFOOD_CONSUMPTION_PER_POPULATION();
		iExtraFood = std::min(iExtraFood, iYields[YIELD_FOOD]*AI_yieldMultiplier(YIELD_FOOD)/100);
		iBaseCostPerTurn -= 4 * iExtraFood * (kOwner.AI_yieldWeight(YIELD_FOOD)-kOwner.AI_yieldWeight(YIELD_PRODUCTION)); // note that we're keeping a factor of 100.
	}

	int iCost = 0; // accumulator for the final return value
	int iScoreLoss = 0;
	for (int i = 0; i < iCitLoss; i++)
	{
		// since the score estimate is very rough, I'm going to flatten it out a bit by combining it with the average score
		job_scores[i] = (2*job_scores[i] + iAverageScore + 2)/3;
		iScoreLoss += job_scores[i];
	}

	for (int i = iCitLoss; i > 0; i--)
	{
		int iFoodLoss = kOwner.getGrowthThreshold(getPopulation() - i) *
				(105 - getMaxFoodKeptPercent()) / 100;
		int iFoodRate = iTotalFood - (iScoreLoss * AI_yieldMultiplier(YIELD_FOOD) * iYields[YIELD_FOOD]
				/*  advc.121b: Round up and then some. Err on the side of under-
					estimating the food rate. */
				+ (2 * 100 * iTotalScore) / 3) /
				std::max(1, iTotalScore * 100);
		iFoodRate -= (getPopulation() - i) * GC.getFOOD_CONSUMPTION_PER_POPULATION();
		iFoodRate += std::min(iWastedFood, i);
		// if we're at the happiness cap, assume we've got some spare food that we're not currently working.
		iFoodRate += iHappyLevel <= 0 ? i : 0;

		int iRecoveryTurns = iFoodRate > 0 ? (iFoodLoss+iFoodRate-1) / iFoodRate : iFoodLoss;

		int iCostPerTurn = iBaseCostPerTurn;
		iCostPerTurn *= iScoreLoss;
		iCostPerTurn /= std::max(1, iTotalScore * 100);

		// extra food from reducing the population:
		iCostPerTurn -= 4 * (std::min(iWastedFood, i) +
				i*GC.getFOOD_CONSUMPTION_PER_POPULATION()) *
				kOwner.AI_yieldWeight(YIELD_FOOD)/100;
		iCostPerTurn += 2*i; // just a little bit of extra cost, to show that we care...

		FAssert(iRecoveryTurns > 0); // iCostPerTurn <= 0 is possible, but it should be rare

		// recovery isn't complete if the citizen is still angry
		iAngerTimer -= iRecoveryTurns;
		if (iAngerTimer > 0 && iHappyLevel + i - iNewAnger < 0)
		{
			iCost += iAngerTimer * GC.getFOOD_CONSUMPTION_PER_POPULATION() * 4 * kOwner.AI_yieldWeight(YIELD_FOOD) / 100;
			iRecoveryTurns += iAngerTimer;
		}

		iCost += iRecoveryTurns * iCostPerTurn;

		iScoreLoss -= job_scores[i-1];
	}
	// if there is any anger left over after regrowing, we might as well count some cost for that too.
	if (iAngerTimer > 0 && iHappyLevel - 1 - iNewAnger < 0)
	{
		int iGrowthTime = std::max(1, iTotalFood - getPopulation()*GC.getFOOD_CONSUMPTION_PER_POPULATION()); // just the food rate here
		iGrowthTime = (kOwner.getGrowthThreshold(getPopulation()) - getFood() + iGrowthTime - 1)/iGrowthTime; // now it's the time.

		iAngerTimer -= iGrowthTime;
		if (iAngerTimer > 0)
		{
			int iCostPerTurn = iBaseCostPerTurn;

			iCostPerTurn *= iAverageScore * (iNewAnger + 1 - iHappyLevel);
			iCostPerTurn /= std::max(1, iTotalScore * 100);

			iCostPerTurn += (iNewAnger + 1 - iHappyLevel) * GC.getFOOD_CONSUMPTION_PER_POPULATION() * 4 * kOwner.AI_yieldWeight(YIELD_FOOD) / 100;

			FAssert(iCostPerTurn > 0 && iAngerTimer > 0);

			iCost += iCostPerTurn * iAngerTimer;
		}
	}
	if (kOwner.AI_getFlavorValue(FLAVOR_GROWTH) > 0)
	{
		iCost *= 120 + kOwner.AI_getFlavorValue(FLAVOR_GROWTH);
		iCost /= 100;
	}

	return iCost;
}

/*	advc: K-Mod formula that was used in two places. I also want to use it in a
	third place. */
int CvCityAI::AI_citizenValue() const
{
	/*	advc.erai (note): Kek-Mod normalizes the era here, but
		I don't think we should assume (implicitly) that mods with fewer eras
		have more perks (like extra tile yields) per era. */
	return 6 + GET_PLAYER(getOwner()).getCurrentEra();
}

